verifier.cmd:
d=$(mktemp -d) && git archive HEAD | tar -x -C "$d" && git show be457dbd829c89e48fbd3f19b72d43864cd97fd8:src/server/http.mjs > "$d/src/server/http.mjs" && cd "$d" && perl -0pi -e 's/(class Buckets \{
)/$1  get size() { return this.m.size; }
  has(k) { return this.m.has(k); }
/; s/(  server\.headersTimeout = 15000;)/  server.rateLimiter = limiter;
$1/; $_ .= "export const MAX_BUCKETS = 10000;
"' src/server/http.mjs && grep -q 'server.rateLimiter = limiter' src/server/http.mjs && grep -q 'get size()' src/server/http.mjs && for n in 'map bounded after every take' 'idle bucket dropped after two minutes' 'http flood keeps every map bounded'; do o=$(node --test --test-reporter=tap --test-name-pattern="$n" test/rate-limit.test.mjs 2>&1); printf '%s
' "$o" | grep -Eq "^ *not ok [0-9]+ - $n" && printf '%s
' "$o" | grep -q 'ERR_ASSERTION' && ! printf '%s
' "$o" | grep -Eq 'TypeError|ReferenceError|RangeError' || exit 1; done
